-- Свип голоса 2026-07 (docs/VOICE.md): в пуле канала «Здоровый Взрослый»
-- 18 фраз из 46 были построены на одном скелете «Это не X. Это Y» — подряд
-- канал читался как одна заготовка. Встроенный фолбэк переписан в
-- src/bot/healthy-adult.data.ts, но публикуется пул из БД
-- (HealthyAdultService.pickFromPool), поэтому засеянные строки надо
-- обновить здесь — иначе фикс до читателей не доедет.
--
-- Идемпотентно: сверка по точному старому тексту. Строку, которую владелец
-- уже поправил в админке, UPDATE не тронет.
-- "updatedAt" проставляется явно: колонка NOT NULL без DEFAULT (Prisma
-- @updatedAt ставит значение на клиенте) — инцидент 2026-07-16.

UPDATE "HealthyAdultPhrase" SET "text" = 'Ты перечитал своё сообщение третий раз и уже придумал, что о тебе подумали. Этому навыку много лет: предугадать чужую реакцию, чтобы успеть подготовиться. Сегодня можно не готовиться.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Ты перечитал своё сообщение третий раз и уже придумал, что о тебе подумали. Это не паранойя. Это старый навык: предугадать чужую реакцию, чтобы успеть подготовиться. Сегодня можно не готовиться.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Ты открыл ноутбук, посмотрел на список дел и закрыл его обратно. Так выглядит перегрузка: пунктов столько, что не за что взяться. Начни с одного, самого маленького.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Ты открыл ноутбук, посмотрел на список дел и закрыл его обратно. Это не лень. Так выглядит перегрузка, когда её слишком много, чтобы начать. Начни с одного пункта, самого маленького.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Ты десятый раз перечитываешь один и тот же абзац и ничего не помнишь. Голова устала и просит перерыв, а не ещё один заход. Закрой, вернёшься.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Ты десятый раз перечитываешь один и тот же абзац и ничего не помнишь. Это не тупость. Это уставшая голова, которой нужен перерыв, а не ещё один заход. Закрой, вернёшься.';

UPDATE "HealthyAdultPhrase" SET "text" = '«Хватит себя жалеть» — знакомая фраза. Но между жалостью и заботой есть разница. Заметить, что тебе тяжело, и отнестись к этому по-человечески — это забота. Возможно, та самая, которой тебе когда-то недодали.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = '«Хватит себя жалеть» — знакомая фраза. Но между жалостью и заботой есть разница. Заметить, что тебе тяжело, и отнестись к этому по-человечески — это не жалость. Это то, чего тебе, возможно, недодали.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Ты называешь это «я всё запустил». Посмотри ближе: ты пережил период, в котором сил хватало только на самое важное. У этого есть имя — режим выживания. Он закончится.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Ты называешь это «я всё запустил». Посмотри ближе: ты пережил период, в котором сил хватало только на самое важное. Это не запущенность. Это режим выживания, и он закончится.';

UPDATE "HealthyAdultPhrase" SET "text" = 'То, что зовут «слишком чувствительный», вблизи оказывается способностью замечать то, что другие проскакивают. У этого есть цена. Поломки в этом нет.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'То, что выглядит как «слишком чувствительный», с другой стороны — способность замечать то, что другие проскакивают. У этого есть цена, но это не поломка.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Разрешение на день: ответить не сразу. Пауза перед ответом — уважение к себе и к тому, что ты хочешь сказать.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Разрешение на день: ответить не сразу. Пауза перед ответом — это не грубость, это уважение к себе и к тому, что ты хочешь сказать.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Достаточно — это разрешение остановиться.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Достаточно — это не планка. Это разрешение остановиться.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Границы отмечают, где заканчиваешься ты и начинается другой.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Границы — это не про то, чтобы оттолкнуть. Это про то, где заканчиваешься ты и начинается другой.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Откат после хорошего периода не отменяет сам период. Ты в низкой точке волны. Волна на то и волна.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Откат после хорошего периода не отменяет сам период. Ты не «всё растерял», ты просто в низкой точке волны. Волна на то и волна.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Пара плохих дней подряд не перечёркивает всё, что было до. Такие уже бывали и проходили — пройдут и эти.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Пара плохих дней подряд не перечёркивает всё, что было до. Это не начало конца, это просто пара плохих дней. Они уже бывали и проходили.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Если ты вернулся к чему-то после долгого перерыва — это смелость: начать заново там, где когда-то не получилось.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Если ты вернулся к чему-то после долгого перерыва — это не «наконец-то соизволил». Это смелость снова начать там, где когда-то не получилось.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Вечер воскресенья часто приходит с тревогой, будто впереди экзамен. Так тело по старой привычке ждёт оценки. Завтра просто понедельник.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Вечер воскресенья часто приходит с тревогой, будто впереди экзамен. Это не про завтра. Это старая привычка тела ждать оценки. Завтра просто понедельник.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Попросить о помощи — по-взрослому обойтись с задачей: взять под неё нужный ресурс.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Попросить о помощи — не значит расписаться в несостоятельности. Это значит, что ты обошёлся с задачей по-взрослому: взял под неё нужный ресурс.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Иногда одиночество — про то, что рядом нет того, кому можно не притворяться. Людей при этом может быть полно. Стоит заметить это, а не списать на себя.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Иногда одиночество — не про то, что рядом никого нет, а про то, что рядом нет того, кому можно не притворяться. Это стоит заметить, а не списать на себя.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Тревога рисует будущее в самых тёмных красках и выдаёт это за прогноз. На деле это черновик страха. Реальность почти всегда пишет иначе.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Тревога рисует будущее в самых тёмных красках и выдаёт это за прогноз. Но это не прогноз, это черновик страха. Реальность почти всегда пишет иначе.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Ты не обязан быть спокойным, чтобы начать. Смелость выглядит так: страшно — и всё равно делаешь маленький шаг.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Ты не обязан быть спокойным, чтобы начать. Смелость — это не отсутствие страха, а когда страшно и всё равно делаешь маленький шаг.';
